"""Prepare original Peatflare Jarrier guides; H3 supplies authored motion."""
import json
from pathlib import Path
import produce as p
UID='unit_neutral_peatflare_jarriers'
LEGACY=p.ROOT/'art/animation/source/poses'/UID
FRAMES=json.loads((LEGACY/'packing.json').read_bytes())['frames']
IDENTITY=('One original adult human Peatflare Jarrier, lean pale man with dark brown hair tied into a small bun, narrow angular face and green neck scarf. Ragged dark green-blue cloak, battered brown leather jerkin with crossed chest straps, dark trousers, wrapped brown forearms and tall leather boots. Three dark round corked peat jars with small orange glowing cracks at the belt; original RIGHT hand on screen left holds one compact orange-glowing round dark jar in ready, and original LEFT hand screen right is empty. Exactly two arms, two hands and two legs, unchanged face, clothes, three belt jars and held jar. No weapons, staffs, bottles elongated into swords or extra jars. ')
PLATE=(' Locked elevated three-quarter orthographic camera facing screen right. Full creature, hands, boots, jars and cloak within960x544 generous margins; unchanged anatomical size and centered root. Uniform saturated magenta RGB255,0,255 background in EVERY frame, no floor, gradients, shadow, color changes, text, particles, magic, other people or props. Real articulated joints, stable hand count and prop size. ')
def ref(index):
 f=dict(FRAMES[index]);f['source']=(LEGACY/f['source']).relative_to(p.ROOT).as_posix();f['alpha_noise_cutoff']=8
 if index<17:f['scale']*=.95
 return f
def config(clip,indices,guides,last,description,seed):
 c=dict(unit_id=UID,clip=clip,canvas=[960,544],anchor=[470,480],scale=.5,key_rgb=[255,0,255],seed=seed,references=[ref(i) for i in indices],guides=guides,last=last,prompt=(IDENTITY+description+PLATE).strip(),protected_foreground_chroma=35,tiled_decode=dict(tile_size=512,overlap=64,temporal_size=16,temporal_overlap=4))
 out=p.SOURCE_DIR/(clip+'_h3_v1');out.mkdir(exist_ok=True);assert not (out/'submission.json').exists();p.write(out/'config.json',c);p.prepare(out,c);p.verify(out,c)
